import{_ as i,a,c as e,ac as l}from"./chunks/framework.BSuaGltH.js";const c=JSON.parse('{"title":"MySQL 事务与并发：锁定读取、幂等和失败回滚","description":"通过两个独立连接竞争最后库存，理解隔离级别、锁等待、死锁与完整事务重试边界。","frontmatter":{"title":"MySQL 事务与并发：锁定读取、幂等和失败回滚","description":"通过两个独立连接竞争最后库存，理解隔离级别、锁等待、死锁与完整事务重试边界。","showdocs":{"topics":[{"id":"mysql","title":"MySQL","link":"/topics/mysql/"}],"kind":"知识专题","scope":"general","audience":"general","group":"数据库与存储","seriesTitle":"MySQL 8.4 实践课程","summary":"通过两个独立连接竞争最后库存，理解隔离级别、锁等待、死锁与完整事务重试边界。","status":"active","related":[{"title":"MySQL 操作与命令","link":"/middleware/mysql/plus/ecosystem/mysql-general-general","kind":"知识专题","scope":"general","audience":"general"},{"title":"MySQL 查询练习：筛选、NULL 与分页","link":"/middleware/mysql/query-exercises","kind":"应用实践","scope":"general","audience":"general"},{"title":"MySQL 查询语法与函数","link":"/middleware/mysql/plus/subjects/mysql-select-base","kind":"知识专题","scope":"general","audience":"general"},{"title":"MySQL 基础概念对照","link":"/middleware/mysql/plus/subjects/mysql-base","kind":"知识专题","scope":"general","audience":"general"},{"title":"MySQL 基础概念对照 · 字符集至其他类似的数据库","link":"/middleware/mysql/plus/subjects/mysql-base-part-02","kind":"知识专题","scope":"general","audience":"general"}],"prev":{"text":"MySQL 建模与查询：约束、关联、分页和复合索引","link":"/middleware/mysql/base/intermediate/model"},"next":{"text":"MySQL 完整应用：Python 库存预留 CLI","link":"/middleware/mysql/plus/practice/application"}},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"MySQL 建模与查询：约束、关联、分页和复合索引","link":"/middleware/mysql/base/intermediate/model"},"next":{"text":"MySQL 完整应用：Python 库存预留 CLI","link":"/middleware/mysql/plus/practice/application"}},"headers":[],"relativePath":"middleware/mysql/base/advanced/transactions.md","filePath":"middleware/mysql/base/advanced/transactions.md"}'),n={name:"middleware/mysql/base/advanced/transactions.md"};function t(p,s,r,h,k,d){return a(),e("div",null,[...s[0]||(s[0]=[l(`<h1 id="mysql-事务与并发-锁定读取、幂等和失败回滚" tabindex="-1">MySQL 事务与并发：锁定读取、幂等和失败回滚 <a class="header-anchor" href="#mysql-事务与并发-锁定读取、幂等和失败回滚" aria-label="Permalink to &quot;MySQL 事务与并发：锁定读取、幂等和失败回滚&quot;">​</a></h1><p>本轮仅全文静态审计，未安装依赖、启动服务、连接数据库或执行任何示例。下文实测、RED/GREEN及平台结果均为此前历史证据；本轮修改后的脚本未运行，命令与输出作为学习步骤和预期保留。</p><h2 id="isolation" tabindex="-1">原子性与隔离级别 <a class="header-anchor" href="#isolation" aria-label="Permalink to &quot;原子性与隔离级别 {#isolation}&quot;">​</a></h2><p>前置：<a href="/middleware/mysql/base/intermediate/model#schema">表约束</a>。库存扣减和预留写入必须全部提交或全部回滚，否则会出现扣了库存却没有记录。InnoDB事务提供原子性；持久性仍依赖数据库配置、存储和恢复策略，不能用“一次COMMIT”替代备份。</p><p>MySQL 8.4.7默认REPEATABLE READ。普通SELECT通常读一致性快照，FOR UPDATE是锁定读取，读取当前可锁定版本；不要把两者混成“一个事务内所有SELECT都一样”。READ COMMITTED每次一致性读取可看到新的已提交快照，减少部分间隙锁场景，但没有消除所有锁或死锁。SERIALIZABLE更强但可能增加阻塞，不能当所有竞争的无代价修补。</p><p>项目对每次reserve显式启动READ COMMITTED事务，而不是改全局默认。事务之间看不到彼此未提交的扣减，写入仍需要锁协调。应用在一个连接上串行执行该事务；不同线程各建自己的连接，不共享游标。</p><h2 id="locking" tabindex="-1">最后库存的竞争 <a class="header-anchor" href="#locking" aria-label="Permalink to &quot;最后库存的竞争 {#locking}&quot;">​</a></h2><p>错误算法是两个连接各读到stock=1，然后都执行UPDATE/INSERT。即使每句SQL本身原子，跨语句业务检查仍不原子。项目先用主键sku执行SELECT ... FOR UPDATE，持有产品行排他锁至COMMIT/ROLLBACK，第二个连接等待，第一个提交后第二个读到0，返回insufficient stock。</p><p>可在两个mysql终端演示，先确保book存在：</p><div class="language-sql vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 会话A</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">START TRANSACTION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stock </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sku</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;book&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FOR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 暂不提交；完成观察后执行 ROLLBACK;</span></span></code></pre></div><div class="language-sql vp-adaptive-theme"><button title="复制代码" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- 会话B</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> SESSION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> innodb_lock_wait_timeout</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">START TRANSACTION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SELECT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> stock </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> products </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> sku</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;book&#39;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FOR</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">ROLLBACK</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>B在A持锁时收到1205。测试脚本使用真正的独立连接和线程屏障验证“两个请求争一个pen仅一人成功”，并核对最终库存0、记录1条，不用单线程正例冒充并发验证。查询条件必须有合适索引，范围锁与扫描范围可能放大阻塞。此实验以主键等值查存在行，不证明任意范围和间隙锁场景。</p><h2 id="idempotency" tabindex="-1">幂等键与参数不匹配 <a class="header-anchor" href="#idempotency" aria-label="Permalink to &quot;幂等键与参数不匹配 {#idempotency}&quot;">​</a></h2><p>request_id主键是调用方的一次业务意图标识。相同ID、sku、quantity重放返回replayed=true，不重复扣减；相同ID配不同参数返回错误，而不是误报旧成功。数据库唯一约束是最终防线，不能仅在内存set中去重。已存在请求必须仍可关联原产品，此模型没有物理删除产品或预留的功能。</p><p>跨sku同时复用同一ID时，不同产品锁不能互相串行化，唯一键仍会拒绝其中一个事务并整体回滚；应用可能收到1062。调用方应避免跨业务意图复用ID。对提交响应丢失的情况，使用原ID和原参数重新查询或调用，以确认结果；生成新ID重试会重复业务。</p><h2 id="failures" tabindex="-1">回滚、死锁与重试边界 <a class="header-anchor" href="#failures" aria-label="Permalink to &quot;回滚、死锁与重试边界 {#failures}&quot;">​</a></h2><p>verify.py在UPDATE成功后注入RuntimeError，断言库存仍为3且没有fail请求，证明except路径确实rollback。CHECK 3819由数据库拒绝负库存；输入验证更早拒绝零、负数、超长键。客户端异常、断连、锁等待或提交失败都不能直接假定成功或失败，尤其COMMIT结果丢失应走幂等确认。</p><p>1205是锁等待超时，1213是检测到死锁后选为牺牲事务。两者不是同一种错误。默认超时可能只回滚当前语句，因此应用统一显式回滚整个业务事务；死锁后也从头重建事务。若要自动重试，只对可重试错误做有界次数和退避，每次从事务起点开始，并保留相同幂等键；验证错误、库存不足、参数冲突不应盲重试。本课程CLI直接非零退出，未实现隐式重试策略。</p><p>多行更新按一致顺序锁行、保持事务短、不要持锁等待用户输入/远程HTTP，可降低死锁概率但不能保证永不死锁。诊断用SHOW ENGINE INNODB STATUS与performance_schema锁表，见<a href="/middleware/mysql/plus/practice/operations#locks">运维排错</a>。</p><p>研究依据：<a href="https://dev.mysql.com/doc/refman/8.4/en/innodb-locking-reads.html" target="_blank" rel="noopener noreferrer">锁定读取</a>、<a href="https://dev.mysql.com/doc/refman/8.4/en/innodb-deadlocks-handling.html" target="_blank" rel="noopener noreferrer">死锁处理</a>。</p><p>自检练习：<a href="/middleware/mysql/pro/review/review#exercises">题4至6</a>。提示：标出锁释放点与事务归属；pen经过verify后为0，竞争前先重置为1并用新请求ID；<a href="/middleware/mysql/pro/review/review#answers">解答</a>另列。</p>`,21)])])}const y=i(n,[["render",t]]);export{c as __pageData,y as default};
